      SUBROUTINE BVGETCC     GET PARAMETERS DESCRIBING HIGHER ORDER AND C     NON-MIDPLANE-SYMMETRIC FIELD COMPONENTS OF A BENDING MAGNET FIELDCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM4C.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'NXRAN.CIN'      INCLUDE 'XRAN.CIN'      INCLUDE 'XRAN4.CIN'CC     LOCAL VARIABLESC      INTEGER  IADR, IBDB, IBDBP, IGAM, IK1P, IK2, IK2P, IK3      INTEGER  INP, IRNMS, IVR, J, NXR      REAL  DATAR      EXTERNAL DATARCC-------------------------------------------------------------------C     RANDOM NUMBERS FOR ERRORSC      NXR = NXRAN(4)      DO 10 J = 1, NXR   10 XRAN(J) = XRAN4(J)CC     SCALING FACTOR FOR NON-MIDPLANE-SYMMETRIC FIELD COMPONENTSC      IRNMS = IPTOJ(NRNMS)      IF (IRNMS .NE. 0) THEN        IADR = I + IRNMS        RNMS = DATAR(IADR)      ELSE        RNMS = RNMSI      ENDIF      IF (PRAN4(NRNMS) .NE. 0.0)     1    RNMS = RNMS + PRAN4(NRNMS)*XRAN(NRNMS)CC     NON-MIDPLANE-SYMMETRIC NORMALIZED BENDING FIELDC      IVR = IPTOJ(NVR)      IF (IVR .NE. 0) THEN        IADR = I + IVR        VRN = DATAR(IADR)      ELSE        VRN = VRNI      ENDIF      IF (PRAN4(NVR) .NE. 0.0)     1    VRN = VRN + PRAN4(NVR)*XRAN(NVR)CC     NON-MIDPLANE-SYMMETRIC NORMALIZED FIELD GRADIENTC      INP = IPTOJ(NNP)      IK1P = IPTOJ(NK1P)      IF (IK1P .EQ. 0 .AND. PRAN4(NK1P) .EQ. 0.0) THEN        IF (INP .EQ. 0) THEN          NPN = NPNI        ELSE           IADR = I + INP          NPN = DATAR(IADR)        ENDIF        IF (PRAN4(NNP) .NE. 0.0) NPN = NPN + PRAN4(NNP)*XRAN(NNP)      ELSE         IF (IK1P .EQ. 0) THEN          K1P = 0.0        ELSE          IADR = I + IK1P          K1P = DATAR(IADR)        ENDIF        IF (PRAN4(NK1P) .NE. 0.0) K1P = K1P + PRAN4(NK1P)*XRAN(NK1P)        K1P = K1P/UNITI(8)**2        IF (H0 .NE. 0.0) NPN = - K1P/H0**2      ENDIFCC     MIDPLANE SYMMETRIC NORMALIZED FIELD SECOND DERIVATIVEC      IBDB = IPTOJ(NBDB)      IK2 = IPTOJ(NK2)      IF (IBDB .NE. 0) THEN        IADR = I + IBDB        BDB = DATAR(IADR)        IF (PRAN4(NBDB) .NE. 0.0) BDB = BDB + PRAN4(NBDB)*XRAN(NBDB)      ELSE IF (IK2 .NE. 0) THEN        IADR = I + IK2        K2 = DATAR(IADR)        IF (PRAN4(NK2) .NE. 0.0) K2 = K2 + PRAN4(NK2)*XRAN(NK2)        K2 = K2/UNITI(8)**3        IF (MPMAD) K2 = 0.5*K2        IF (H0 .NE. 0.0) BDB = K2/H0      ELSE        BDB = BDBI        IF (PRAN4(NBDB) .NE. 0.0) BDB = BDB + PRAN4(NBDB)*XRAN(NBDB)      ENDIFCC     NON-MIDPLANE SYMMETRIC NORMALIZED FIELD SECOND DERIVATIVEC      IBDBP = IPTOJ(NBDBP)      IK2P = IPTOJ(NK2P)      IF (IK2P .EQ. 0 .AND. PRAN4(NK2P) .EQ. 0.0) THEN        IF (IBDBP .EQ. 0) THEN          BDBP = BDBPI        ELSE          IADR = I + IBDBP          BDBP = DATAR(IADR)        ENDIF        IF (PRAN4(NBDBP) .NE. 0.0)     1      BDBP = BDBP + PRAN4(NBDBP)*XRAN(NBDBP)      ELSE        IF (IK2P .EQ. 0) THEN          K2P = 0.0        ELSE          IADR = I + IK2P          K2P = DATAR(IADR)        ENDIF        IF (PRAN4(NK2P) .NE. 0.0) K2P = K2P + PRAN4(NK2P)*XRAN(NK2P)        IF (MPMAD) K2P = 0.5*K2P        K2P = K2P/UNITI(8)**3        IF (H0 .NE. 0.0) BDBP = K2P*UNITI(1)**2/H0      ENDIFCC     MIDPLANE SYMMETRIC NORMALIZED FIELD THIRD DERIVATIVEC      IGAM = IPTOJ(NGAM)      IK3 = IPTOJ(NK3)      IF (IGAM .NE. 0) THEN        IADR = I + IGAM        GAM = DATAR(IADR)        IF (PRAN4(NGAM) .NE. 0.0) GAM = GAM + PRAN4(NGAM)*XRAN(NGAM)      ELSE IF (IK3 .NE. 0) THEN        IADR = I + IK3        K3 = DATAR(IADR)        IF (MPMAD) K3 = K3/6.0        K3 = K3/UNITI(8)**4        GAM = K3*UNITI(1)**3/H0      ELSE        GAM = GAMI        IF (PRAN4(NGAM) .NE. 0.0) GAM = GAM + PRAN4(NGAM)*XRAN(NGAM)      ENDIF      RETURN      END